<?php elseif($page==='item'):$id=(int)($_GET['id']??0);$st=$db->prepare("SELECT p.*,u.name seller,u.college,u.id seller_id,(SELECT AVG(r.rating) FROM reviews r WHERE r.seller_id=u.id) seller_rating FROM products p JOIN users u ON u.id=p.seller_id WHERE p.id=? AND p.status IN ('available','reserved')");$st->execute([$id]);$item=$st->fetch();?><main class="page-shell"><?php if(!$item):?><div class="empty-state"><h2>Listing not found</h2><a href="?page=browse">Back to marketplace</a></div><?php else:?><a class="back-link" href="?page=browse">← Back to marketplace</a><div class="item-layout"><div class="item-photo"><?php if($item['image']):?><img src="uploads/<?=h($item['image'])?>" alt="<?=h($item['title'])?>"><?php else:?><span class="placeholder">✳</span><?php endif?></div><div class="item-detail"><div class="eyebrow"><?=h($item['category'])?> · <?=h($item['item_condition'])?> condition</div><h1><?=h($item['title'])?></h1><div class="item-price"><?=$item['listing_type']==='free'?'Free':'₹'.number_format((float)$item['price'],0)?></div><p><?=nl2br(h($item['description']))?></p><div class="seller-box"><span class="avatar"><?=h(strtoupper(substr($item['seller'],0,1)))?></span><div><b><?=h($item['seller'])?></b><small><?=h($item['college'])?><?= $item['seller_rating']?' · ★ '.number_format((float)$item['seller_rating'],1):''?></small></div></div><?php if($u && $u['id']!=$item['seller_id']):?><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="message"><input type="hidden" name="product_id" value="<?=$id?>"><label>Message seller<textarea name="body" required placeholder="Hi! Is this still available?"></textarea></label><button class="button full">Send a message ↗</button></form><details class="offer-details"><summary>Make an offer</summary><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="offer"><input type="hidden" name="product_id" value="<?=$id?>"><label>Your offer (₹)<input type="number" name="amount" min="1" step="1" required></label><label>Note <input name="message" maxlength="500" placeholder="Optional message"></label><button class="button secondary">Send offer</button></form></details><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="report"><input type="hidden" name="product_id" value="<?=$id?>"><input required name="reason" placeholder="Reason for report" class="report-input"><button class="text-button">Report listing</button></form><?php elseif(!$u):?><a class="button full" href="?page=login">Sign in to contact seller</a><?php else:?><a class="button secondary" href="?page=account">Manage your listing</a><?php endif?></div></div><?php endif?></main>
