lue="<?=h($editing['age']??'')?>"></label><label>Description<textarea required name="description" id="description" rows="5" placeholder="What should someone know about it?"><?=h($editing['description']??'')?></textarea></label><button class="button secondary" type="button" id="generate">✳ Help me write a description</button><label>Photo (JPG, PNG or WEBP, up to 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><button class="button full"><?=$editing?'Save changes':'Publish listing'?> ↗</button></form></main>
