<?php elseif($page==='messages'):need_user();$st=$db->prepare('SELECT c.*,p.title,ub.name buyer,us.name seller,(SELECT body FROM messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) latest FROM conversations c JOIN products p ON p.id=c.product_id JOIN users ub ON ub.id=c.buyer_id JOIN users us ON us.id=c.seller_id WHERE c.buyer_id=? OR c.seller_id=? ORDER BY c.id DESC');$st->execute([$u['id'],$u['id']]);$convos=$st->fetchAll();?><main class="page-shell narrow"><div class="eyebrow">YOUR INBOX</div><h1>Conversations.</h1><?php foreach($convos as $c):?><section class="panel"><div class="eyebrow"><?=h($c['title'])?> · with <?=h($c['buyer_id']==$u['id']?$c['seller']:$c['buyer'])?></div><div class="chat-log"><?php $m=$db->prepare('SELECT m.*,u.name FROM messages m JOIN users u ON u.id=m.sender_id WHERE conversation_id=? ORDER BY id');$m->execute([$c['id']]);foreach($m as $msg):?><p class="chat-message"><b><?=h($msg['name'])?>:</b> <?=h($msg['body'])?></p><?php endforeach?></div><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="message"><input type="hidden" name="conversation_id" value="<?=$c['id']?>"><input required name="body" placeholder="Write a reply…"><button class="button small">Send</button></form></section><?php endforeach?><?php if(!$convos):?><div class="empty-state"><span>↗</span><h3>Your conversations will live here.</h3><p>Open a listing and message its seller to get started.</p></div><?php endif?></main>
<?php elseif($page==='offers'):need_user();$st=$db->prepare('SELECT o.*,p.title,ub.name buyer,us.name seller FROM offers o JOIN products p ON p.id=o.product_id JOIN users ub ON ub.id=o.buyer_id JOIN users us ON us.id=o.seller_id WHERE o.buyer_id=? OR o.seller_id=? ORDER BY o.created_at DESC');$st->execute([$u['id'],$u['id']]);?><main class="page-shell narrow"><div class="eyebrow">PRICE NEGOTIATION</div><h1>Your offers.</h1><?php foreach($st as $o):?><section class="panel"><div class="eyebrow"><?=h($o['title'])?> · <?=h($o['status'])?></div><h3>₹<?=number_format((float)$o['amount'],0)?> <small>from <?=h($o['buyer'])?></small></h3><p><?=h($o['message'])?></p><?php if($o['seller_id']==$u['id']&&$o['status']==='pending'):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="offer_status"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="button small" name="status" value="accepted">Accept</button><button class="button secondary small" name="status" value="rejected">Decline</button></form><?php endif?></section><?php endforeach?></main>
<?php elseif($page==='transactions'):need_user();$st=$db->prepare('SELECT t.*,p.title,ub.name buyer,us.name seller FROM transactions t JOIN products p ON p.id=t.product_id JOIN users ub ON ub.id=t.buyer_id JOIN users us ON us.id=t.seller_id WHERE t.buyer_id=? ORDER BY t.created_at DESC');$st->execute([$u['id']]);?><main class="page-shell narrow"><div class="eyebrow">HANDOVERS</div><h1>Transactions.</h1><?php foreach($st as $t):?><section class="panel"><div class="eyebrow"><?=h($t['status'])?></div><h3><?=h($t['title'])?></h3><p>Buyer: <?=h($t['buyer'])?> · Seller: <?=h($t['seller'])?></p><?php if($t['status']==='arranging'):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="transaction_status"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="button small" name="status" value="completed">Mark completed</button><button class="button secondary small" name="status" value="cancelled">Cancel</button></form><?php elseif($t['status']==='completed'&&$t['buyer_id']==$u['id']):?><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="review"><input type="hidden" name="transaction_id" value="<?=$t['id']?>"><select name="rating"><option value="5">★★★★★</option><option value="4">★★★★</option><option value="3">★★★</option><option value="2">★★</option><option value="1">★</option></select><input name="body" placeholder="Share a quick review"><button class="button small">Review seller</button></form><?php endif?></section><?php endforeach?></main>
<?php elseif($page==='notifications'):need_user();$db->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['id']]);$st=$db->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$st->execute([$u['id']]);?><main class="page-shell narrow"><div class="eyebrow">WHAT'S NEW</div><h1>Your updates.</h1><?php foreach($st as $n):?><a class="panel notification" href="<?=h($n['link']?:'#')?>"><b><?=h($n['body'])?></b><small><?=h($n['created_at'])?></small></a><?php endforeach?></main>
